const postedResult = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Posted Result',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Pair each Post Journal Entry response with its entry; build the result email, the\n// close-log row and the WIP to COGS Moves rows for the WIP entries that posted.\nconst p = $('Build Proposal').first().json;\nconst P = $('Set Period').first().json;\nconst sent = $('Guard Before Posting').all().map(i => i.json);\nconst resp = $input.all().map(i => i.json);\nconst money = n => (n < 0 ? '-$' : '$') + Math.abs(Number(n) || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\nconst now = new Date().toISOString();\nconst res = sent.map((s, i) => {\n  const r = resp[i] || {};\n  const id = r.JournalEntry && r.JournalEntry.Id;\n  return { doc: s.doc, key: s.key, total: s.total, id: id || '', err: id ? '' : JSON.stringify(r.Fault || r.error || r).slice(0, 400) };\n});\nconst moves = [];\nfor (const r of res) {\n  if (!r.id || r.key === 'INV') continue;\n  const e = p.entries.find(x => x.doc === r.doc);\n  for (const m of e.moves) moves.push(Object.assign({}, m, { qbo_je_id: String(r.id), posted_at: now }));\n}\nconst failed = res.filter(r => !r.id);\nconst html = '<div style=\"font-family:Segoe UI,Arial;font-size:13px\"><p><b>' + (failed.length ? failed.length + ' entr' + (failed.length > 1 ? 'ies' : 'y') + ' FAILED.' : 'Posted.') + '</b> WIP, COGS &amp; inventory month-end ' + p.label + ':</p><ul>' +\n  res.map(r => '<li>' + r.doc + ' ' + money(r.total) + ' - ' + (r.id ? 'posted, QuickBooks JE id ' + r.id : 'FAILED: ' + r.err.replace(/</g, '&lt;')) + '</li>').join('') +\n  (sent[0].skipped || []).map(s => '<li>' + s + ' - skipped</li>').join('') + '</ul></div>';\nconst sum = k => res.filter(r => r.id && (k === 'INV' ? r.key === 'INV' : r.key !== 'INV')).reduce((s, r) => s + r.total, 0);\nreturn [{ json: {\n  subject: (failed.length ? '[FAILED] ' : '[POSTED] ') + 'WIP, COGS & inventory month-end ' + p.label,\n  html, moves,\n  log: { period: p.period, status: failed.length ? (failed.length === res.length ? 'failed' : 'partly posted') : 'posted',\n    doc_numbers: res.map(r => r.doc).join(', '), wip_to_cogs: Math.round(sum('WIP') * 100) / 100, inventory_trueup: Math.round(sum('INV') * 100) / 100,\n    qbo_je_ids: res.map(r => r.id || 'failed').join(', '), detail: failed.map(f => f.doc + ': ' + f.err).join(' | ').slice(0, 2000),\n    run_at: P.runAt, execution_id: String($execution.id) },\n} }];\n" } } });
const notPosted = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Not Posted',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Declined, expired, or blocked by the guard: nothing is posted.\nconst p = $('Build Proposal').first().json;\nconst P = $('Set Period').first().json;\nconst j = $input.first().json;\nlet status, why;\nif ('clear' in j) { status = 'blocked'; why = j.why; }\nelse { const a = j.data || {}; status = a.approved === false ? 'declined' : 'expired'; why = status === 'declined' ? 'declined by email' : 'no response within ' + P.approvalDays + ' days'; }\nreturn [{ json: {\n  subject: '[NOT POSTED] WIP, COGS & inventory month-end ' + p.label + ' - ' + status,\n  html: '<div style=\"font-family:Segoe UI,Arial;font-size:13px\"><p><b>Not posted</b> (' + String(why).replace(/</g, '&lt;') + '). Run the month again (Run Now with MONTH_OVERRIDE = \"' + p.period + '\" in Set Period) for a fresh proposal.</p></div>',\n  moves: [],\n  log: { period: p.period, status, doc_numbers: p.toPostDocs.join(', '), wip_to_cogs: 0, inventory_trueup: 0, qbo_je_ids: '', detail: String(why).slice(0, 2000), run_at: P.runAt, execution_id: String($execution.id) },\n} }];\n" } } });
const reportOnly = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Report Only',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Nothing to approve (nothing to post, cannot post, or SEND_FOR_APPROVAL is off). The\n// report email already went out; log it.\nconst p = $('Build Proposal').first().json;\nconst P = $('Set Period').first().json;\nconst status = p.issues.length ? 'cannot_post' : (p.toPostDocs.length ? 'report_only' : 'nothing_to_post');\nreturn [{ json: { skipEmail: true, moves: [],\n  log: { period: p.period, status, doc_numbers: p.toPostDocs.join(', '), wip_to_cogs: 0, inventory_trueup: 0, qbo_je_ids: '',\n    detail: p.issues.concat(p.flags).join(' | ').slice(0, 2000), run_at: P.runAt, execution_id: String($execution.id) } } }];\n" } } });
