const movesRows = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Moves Rows',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Posted WIP -> COGS lines, recorded in WIP to COGS Moves (same table the Daily WIP to COGS\n// workflow uses), so nothing is moved twice.\nreturn $input.all().flatMap(i => (i.json.moves || []).map(m => ({ json: m })));" } } });
const saveMoves = node({ type: 'n8n-nodes-base.dataTable', version: 1.1, config: { name: 'Save WIP to COGS Moves',
  parameters: { resource: 'row', operation: 'insert', dataTableId: { __rl: true, mode: 'id', value: 'llZwcCsPioI6VB1b', cachedResultName: 'WIP to COGS Moves' }, columns: { mappingMode: 'autoMapInputData', value: null }, options: {} } } });
const snapDay = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Snapshot Day',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Month-end WASP snapshot: the schedule fires every night at 11:50 PM PT and goes on\n// only on the last day of the month, so the true-up uses WASP as of month end.\n// Run Snapshot Now takes one immediately (labelled with the current month).\nconst tz = 'America/Los_Angeles';\nconst now = $now.setZone(tz);\nlet manual = false;\ntry { manual = $('Run Snapshot Now').isExecuted; } catch (e) { manual = false; }\nif (!manual && now.plus({ days: 1 }).day !== 1) return [];\nreturn [{ json: { month: now.toFormat('yyyy-MM'), takenAt: now.toFormat('yyyy-MM-dd HH:mm') } }];\n" } } });
const snapInv = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: 'Get WASP Inventory (snapshot)', executeOnce: true, retryOnFail: true, maxTries: 3, waitBetweenTries: 5000,
  parameters: { method: 'POST', url: 'https://pandawd.waspinventorycloud.com/public-api/ic/item/streamgridrequestcsvflat', authentication: 'genericCredentialType', genericAuthType: 'httpBearerAuth',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: '{}',
    options: { allowUnauthorizedCerts: true, timeout: 300000, response: { response: { responseFormat: 'text', outputPropertyName: 'data' } } } },
  credentials: { httpBearerAuth: { id: '7awrSdjW2myNV459', name: 'WASP API Token' } } } });
const snapRows = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Build Snapshot Rows',  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// WASP item list (In House x Item Cost) -> one row per item/site/location with stock.\nconst S = $('Snapshot Day').first().json;\nconst RAW = {\n  'ACM': '1114', 'ALUMINUM': '1114', 'ALUM - SMALL ITEMS': '1114', 'GLASS': '1112',\n  'HARDWARE SMALL PARTS': '1111', 'SPECIAL HARDWARE': '1111', 'POWDER COATING': '1113',\n  'SHOP SUPPLIES': '1150040019', 'WOOD AT P2': '1121', 'FINISH': '1103',\n};\nconst text = String($input.first().json.data || '');\nif (!text.includes('AssetTag')) throw new Error('WASP inventory did not come back as CSV: ' + text.slice(0, 200));\nconst csv = [];\n{ let row = [], f = '', q = false;\n  for (let i = 0; i < text.length; i++) { const c = text[i];\n    if (q) { if (c === '\"') { if (text[i + 1] === '\"') { f += '\"'; i++; } else q = false; } else f += c; }\n    else if (c === '\"') q = true; else if (c === ',') { row.push(f); f = ''; } else if (c === '\\n') { row.push(f); csv.push(row); row = []; f = ''; } else if (c !== '\\r') f += c; }\n  if (f || row.length) { row.push(f); csv.push(row); } }\nconst hdr = csv.shift();\nconst ci = n => { const i = hdr.indexOf(n); if (i < 0) throw new Error('WASP CSV missing ' + n); return i; };\nconst I = { tag: ci('AssetTag'), desc: ci('AssetDescription'), cat: ci('CategoryDescription'), cost: ci('ItemCost'), qty: ci('TotalInHouse'), site: ci('SiteName'), loc: ci('LocationCode') };\nconst out = [];\nfor (const r of csv) {\n  const qty = Number(r[I.qty]) || 0;\n  if (!qty || !r[I.tag]) continue;\n  const cat = (r[I.cat] || '').trim() || '(blank)';\n  const cost = Number(r[I.cost]) || 0;\n  out.push({ json: { month: S.month, taken_at: S.takenAt, item: r[I.tag], description: (r[I.desc] || '').replace(/\\s+/g, ' ').trim().slice(0, 250),\n    category: cat, gl_account: RAW[cat.toUpperCase()] || '', site: r[I.site] || '', location: r[I.loc] || '',\n    in_house: qty, item_cost: cost, extended: Math.round(qty * cost * 100) / 100 } });\n}\nif (!out.length) throw new Error('WASP returned no items with stock.');\nreturn out;\n" } } });
const saveSnap = node({ type: 'n8n-nodes-base.dataTable', version: 1.1, config: { name: 'Save Snapshot',
  parameters: { resource: 'row', operation: 'insert', dataTableId: { __rl: true, mode: 'id', value: 'XHwQETgSO7XQ4xxp', cachedResultName: 'WASP Month-End Inventory' }, columns: { mappingMode: 'autoMapInputData', value: null }, options: {} } } });
const note = sticky('## WIP, COGS & inventory month-end\nRuns **5 PM PT on the first business day** of the month for the prior month (weekday schedule; Set Period stops on other days). **Run Now** runs last month; set `MONTH_OVERRIDE` in **Set Period** to redo one.\n1. Ties every line in the WIP sub-accounts to a Shop Updates job (WASP pick / QBO customer:project) and its status at month end.\n2. Proposes **WIPCOGS-YYYY-MM** (Dr COGS / Cr WIP for jobs completed in the month); **WIPCOGS-PRIOR-YYYY-MM** for older completions if `INCLUDE_PRIOR_COMPLETIONS`.\n3. Trues QuickBooks raw materials up to WASP at month end: **INVTRUEUP-YYYY-MM** (Raw Materials vs matching COGS / 5381 Shop Supplies). WASP month end = the **11:50 PM snapshot** taken on the last day (Save Snapshot -> WASP Month-End Inventory); without one, live WASP rolled back (estimate).\n4. Emails the workbook (Summary, WIP, COGS, Inventory True-up, Inventory Detail, All Data), then Approve / Decline. Approve re-checks and posts; moves go to **WIP to COGS Moves**, runs to **WIP Month-End Close Log**.\nThe parent account Inventory Asset:Work in Process (offset) is reported, never changed.\nSource: QBO-PO repo, n8n/wip-month-end/.', { color: 4, position: [0, -420], width: 760, height: 380 });
export default workflow('wip-cogs-inventory-month-end', 'QBO - WIP, COGS & Inventory Month-End (approval by email)')
  .add(daily).to(setPeriod)
  .add(runNow).to(setPeriod)
  .add(setPeriod).to(buildGl).to(getGl).to(getJes).to(getPicks).to(getJobs).to(getTb).to(getSnap).to(getInv).to(getAct).to(findJes).to(buildProp).to(buildWb).to(emailReport)
  .to(sendForApproval
    .onTrue(emailApproval.to(approved
      .onTrue(recheckJes.to(recheckTb).to(guard).to(clear
        .onTrue(postJe.to(postedResult).to(outcome))
        .onFalse(notPosted)))
      .onFalse(notPosted)))
    .onFalse(reportOnly.to(logRow)))
  .add(notPosted).to(outcome)
  .add(outcome).to(emailResult)
  .add(outcome).to(logRow)
  .add(outcome).to(movesRows).to(saveMoves)
  .add(logRow).to(saveLog)
  .add(nightly).to(snapDay)
  .add(snapNow).to(snapDay)
  .add(snapDay).to(snapInv).to(snapRows).to(saveSnap)
  .add(note);
